sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.login = function() {

        if (c.data.loggedIn) {

            window.location.href =
                "?id=cfms_student";

            return;
        }

        var returnURL = encodeURIComponent(
            "?id=cfms_student"
        );

        window.location.href =
            "/login.do?sysparm_url=" + returnURL;
    };


    c.continueToDashboard = function() {

        window.location.href =
            "?id=cfms_student";

    };


    c.goHome = function() {

        window.location.href =
            "?id=cfms_home";

    };

};

sp_widget.css:
.student-login-page {
    min-height: 100vh;
    position: relative;
    overflow: hidden;

    background: #f0fbfc;

    font-family:
        'Segoe UI',
        Tahoma,
        Geneva,
        Verdana,
        sans-serif;

    color: #263238;

    display: flex;
    align-items: center;
    justify-content: center;

    padding: 40px 20px;
}


/* Background circles */

.bg-circle {
    position: absolute;
    border-radius: 50%;
    opacity: 0.35;
    pointer-events: none;
}

.circle-one {
    width: 450px;
    height: 450px;

    background: #4dd0e1;

    top: -220px;
    right: -120px;
}

.circle-two {
    width: 350px;
    height: 350px;

    background: #00acc1;

    bottom: -180px;
    left: -120px;
}


/* Main wrapper */

.login-wrapper {
    width: 100%;
    max-width: 1100px;

    min-height: 650px;

    display: grid;
    grid-template-columns: 1.1fr 0.9fr;

    background: #ffffff;

    border-radius: 28px;

    overflow: hidden;

    position: relative;
    z-index: 2;

    box-shadow:
        0 25px 60px rgba(0, 172, 193, 0.18);
}


/* Left section */

.login-info {
    background: linear-gradient(
        145deg,
        #00acc1,
        #4dd0e1
    );

    padding: 55px;

    color: #ffffff;

    display: flex;
    flex-direction: column;
}


/* Brand */

.brand {
    display: flex;
    align-items: center;
    gap: 14px;
}

.brand-icon {
    width: 50px;
    height: 50px;

    border-radius: 14px;

    background: rgba(255,255,255,0.18);

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 23px;
}

.brand h2 {
    margin: 0;

    font-size: 25px;
    font-weight: 800;
}

.brand span {
    display: block;

    margin-top: 3px;

    font-size: 11px;

    opacity: 0.9;
}


/* Welcome */

.welcome-content {
    margin-top: 90px;
}

.welcome-badge {
    display: inline-flex;

    align-items: center;
    gap: 8px;

    padding: 8px 14px;

    border-radius: 50px;

    background: rgba(255,255,255,0.17);

    font-size: 11px;

    font-weight: 700;

    letter-spacing: 0.8px;
}

.welcome-content h1 {
    margin: 22px 0 15px;

    font-size: 46px;

    line-height: 1.12;

    font-weight: 800;
}

.welcome-content h1 span {
    color: #ffffff;
}

.welcome-content p {
    max-width: 480px;

    font-size: 15px;

    line-height: 1.7;

    opacity: 0.92;

    margin: 0;
}


/* Features */

.features {
    margin-top: auto;

    display: flex;
    flex-direction: column;

    gap: 18px;
}

.feature {
    display: flex;

    align-items: center;

    gap: 14px;
}

.feature-icon {
    width: 42px;
    height: 42px;

    flex-shrink: 0;

    border-radius: 12px;

    background: rgba(255,255,255,0.18);

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 17px;
}

.feature strong {
    display: block;

    font-size: 14px;

    margin-bottom: 3px;
}

.feature span {
    display: block;

    font-size: 12px;

    opacity: 0.85;
}


/* Right card */

.login-card {
    padding: 55px 50px;

    display: flex;

    flex-direction: column;

    justify-content: center;

    background: #ffffff;
}


/* Card header */

.card-header {
    text-align: center;

    margin-bottom: 35px;
}

.student-icon {
    width: 75px;
    height: 75px;

    margin: 0 auto 20px;

    border-radius: 22px;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 30px;
}

.card-header h2 {
    margin: 0;

    font-size: 30px;

    font-weight: 800;

    color: #263238;
}

.card-header p {
    margin: 9px 0 0;

    color: #78909c;

    font-size: 14px;
}


/* Secure message */

.secure-message {
    display: flex;

    align-items: flex-start;

    gap: 13px;

    padding: 17px;

    background: #f0fbfc;

    border: 1px solid #b2ebf2;

    border-radius: 14px;

    margin-bottom: 22px;
}

.secure-message > i {
    color: #00acc1;

    font-size: 18px;

    margin-top: 2px;
}

.secure-message strong {
    display: block;

    font-size: 13px;

    color: #263238;

    margin-bottom: 4px;
}

.secure-message span {
    display: block;

    color: #607d8b;

    font-size: 11px;

    line-height: 1.5;
}


/* Login button */

.login-btn {
    width: 100%;

    border: none;

    border-radius: 12px;

    padding: 15px 20px;

    background: #00acc1;

    color: #ffffff;

    font-size: 14px;

    font-weight: 700;

    cursor: pointer;

    transition: all 0.25s ease;

    box-shadow:
        0 8px 20px rgba(0,172,193,0.22);
}

.login-btn i {
    margin-right: 8px;
}

.login-btn .fa-arrow-right {
    margin-left: 8px;
    margin-right: 0;
}

.login-btn:hover {
    background: #008c9e;

    transform: translateY(-2px);

    box-shadow:
        0 12px 25px rgba(0,172,193,0.28);
}


/* Divider */

.divider {
    display: flex;

    align-items: center;

    gap: 12px;

    margin: 25px 0;

    color: #90a4ae;

    font-size: 11px;

    font-weight: 600;
}

.divider::before,
.divider::after {
    content: "";

    height: 1px;

    background: #e0e0e0;

    flex: 1;
}


/* Back button */

.back-btn {
    width: 100%;

    padding: 13px;

    border: 1px solid #cfd8dc;

    border-radius: 12px;

    background: #ffffff;

    color: #546e7a;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;

    transition: all 0.2s ease;
}

.back-btn i {
    margin-right: 7px;
}

.back-btn:hover {
    border-color: #00acc1;

    color: #00acc1;

    background: #f0fbfc;
}


/* Already login */

.already-login {
    text-align: center;
}

.success-icon {
    width: 60px;
    height: 60px;

    margin: 0 auto 18px;

    border-radius: 50%;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;
    justify-content: center;

    font-size: 24px;
}

.already-login h3 {
    margin: 0 0 8px;

    font-size: 19px;
}

.already-login p {
    margin: 0 0 22px;

    color: #78909c;

    font-size: 13px;
}


/* Footer */

.login-footer {
    text-align: center;

    margin-top: 30px;

    padding-top: 20px;

    border-top: 1px solid #eceff1;

    color: #90a4ae;

    font-size: 10px;
}

.login-footer i {
    color: #00acc1;

    margin-right: 5px;
}


/* Responsive */

@media (max-width: 900px) {

    .login-wrapper {
        grid-template-columns: 1fr;
    }

    .login-info {
        padding: 40px;
    }

    .welcome-content {
        margin-top: 55px;
    }

    .welcome-content h1 {
        font-size: 38px;
    }

    .features {
        margin-top: 45px;
    }

    .login-card {
        padding: 45px 35px;
    }
}


@media (max-width: 600px) {

    .student-login-page {
        padding: 15px;
    }

    .login-wrapper {
        border-radius: 20px;
    }

    .login-info {
        padding: 30px 25px;
    }

    .welcome-content {
        margin-top: 40px;
    }

    .welcome-content h1 {
        font-size: 32px;
    }

    .login-card {
        padding: 35px 25px;
    }

    .card-header h2 {
        font-size: 26px;
    }
}

sp_widget.script:
(function() {

    data.loggedIn = gs.isLoggedIn();

    data.userName = "";
    data.userEmail = "";

    if (data.loggedIn) {

        var user = gs.getUser();

        data.userName = user.getName();
        data.userEmail = user.getEmail();

    }

})();
